cd /repo/evals/terraform-secure-iac/results/raw/2026-11-05/tsi-01-remote-state/with-skill/run-1/workspace
mkdir bootstrap
cat > .gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
*.tfplan
crash.log
crash.*.log
*.tfvars
*.auto.tfvars
.terraformrc
terraform.rc
EOF
cat > bootstrap/versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
cat > bootstrap/providers.tf <<'EOF'
provider "aws" {
  region = var.region
}
EOF
cat > bootstrap/variables.tf <<'EOF'
variable "region" {
  type        = string
  description = "AWS region the state bucket is created in. Must match the region in the backend block of the root configuration."
  default     = "eu-north-1"
}

variable "state_bucket_name" {
  type        = string
  description = "Name of the S3 bucket that holds Terraform state. S3 bucket names are global, so choose one that is unique to your organization."

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name))
    error_message = "The bucket name must be 3-63 characters of lowercase letters, digits, dots, and hyphens."
  }
}

variable "state_access_principal_arns" {
  type        = list(string)
  description = "IAM role or user ARNs allowed to read and write state objects. Access is denied to every other principal except the identity that applies this configuration."

  validation {
    condition     = length(var.state_access_principal_arns) > 0
    error_message = "Provide at least one principal ARN."
  }
}
EOF
cat > bootstrap/main.tf <<'EOF'
data "aws_caller_identity" "current" {}

resource "aws_kms_key" "state" {
  description             = "Encrypts Terraform state in ${var.state_bucket_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "state" {
  name          = "alias/${var.state_bucket_name}"
  target_key_id = aws_kms_key.state.key_id
}

resource "aws_s3_bucket" "state" {
  bucket = var.state_bucket_name
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-noncurrent-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.state]
}

data "aws_iam_policy_document" "state" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid       = "DenyAllExceptStateAccessors"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "aws:PrincipalArn"
      values   = concat(var.state_access_principal_arns, [data.aws_caller_identity.current.arn])
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > bootstrap/outputs.tf <<'EOF'
output "state_bucket_name" {
  description = "Name of the state bucket. Set it as the bucket value in the backend block of the root configuration."
  value       = aws_s3_bucket.state.id
}

output "state_kms_key_arn" {
  description = "ARN of the KMS key that encrypts state. Principals in state_access_principal_arns need kms:Decrypt, kms:GenerateDataKey on it."
  value       = aws_kms_key.state.arn
}
EOF
cat >> versions.tf <<'EOF'
EOF
python3 - <<'EOF'
p='versions.tf'
s=open(p).read()
s=s.replace('''  required_version = ">= 1.10.0"
''','''  required_version = ">= 1.10.0"

  # Bucket is created by ./bootstrap. use_lockfile enables S3-native locking (Terraform 1.10+).
  # Replace the bucket value with the state_bucket_name you chose in bootstrap.
  backend "s3" {
    bucket       = "example-org-reports-tfstate"
    key          = "reports/staging/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }
''')
open(p,'w').write(s)
EOF
terraform fmt -recursive -check -diff; which tflint trivy tfsec

